def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    # Check if fixity has a 'files' key
    if 'files' not in fixity:
        raise ValueError("Fixity must have a 'files' key")

    # Check if the 'files' key is a list
    if not isinstance(fixity['files'], list):
        raise ValueError("The 'files' key in fixity must be a list")

    # Check if all files in the 'files' list are in the manifest
    for file in fixity['files']:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' in fixity is not in the manifest")

    # Check if the fixity block has any other keys
    for key in fixity:
        if key != 'files':
            raise ValueError(f"Fixity block has an invalid key: {key}")

    return True

