    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The dictionary containing the parsed spec file.

    Returns:
        dict: The updated dictionary with the included groups.
    """
    # Initialize the output dictionary
    output_dict = {}

    # Iterate over the keys in the input dictionary
    for key, value in parser_dict.items():
        # If the value is a dictionary, recursively call this function
        if isinstance(value, dict):
            output_dict[key] = self._include_groups(value)
        # If the value is a list, iterate over the items in the list
        elif isinstance(value, list):
            output_dict[key] = []
            for item in value:
                # If the item is a dictionary, recursively call this function
                if isinstance(item, dict):
                    output_dict[key].append(self._include_groups(item))
                # Otherwise, add the item to the output list
                else:
                    output_dict[key].append(item)
        # If the value is a string, check if it is an include directive
        elif isinstance(value, str):
            # If the value is an include directive, parse it and add the included groups to the output dictionary
